"""Saved terminal evidence to a static HTML report; no scientific imports."""
import gzip
import hashlib
import html
import json
import os
import subprocess
from decimal import Decimal
from pathlib import Path
from report_evidence import ROOT, PUB, PREFIX, DEST, pin, load, project

HERE = Path(__file__).resolve().parent
BASE = '26ab0339fd7d7ae15f0f18af3ac8ae29759605e9'
MAIN = 'docs/research/gcts-rl-renewal/index.html'
AUDIT = ROOT / '.gcts-active/family-pool-independent-audit-20261012'


def math(value):
    return r'\(' + html.escape(str(value)) + r'\)'


def table(headers, rows):
    return '<div class="table-scroll"><table><thead><tr>' + ''.join('<th>'+html.escape(h)+'</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows) + '</tbody></table></div>'


def main():
    result, life, terminal = load(AUDIT/'audit-result-v1.json'), load(AUDIT/'audit-lifetime-v1.json'), load(HERE/'audit-terminal-v1.json')
    assert result['status'] == 'passed_complete_independent_static_family_pool_audit'
    assert life['status'] == 'passed_owned_independent_static_family_pool_audit' and life['child_reaped']
    assert terminal['status'] == 'passed_ROOT_owned_static_pool_dispatch' and terminal['owner_process_terminal_reaped']
    assert pin(AUDIT/'audit-lifetime-v1.json') == {k:terminal['lifetime'][k] for k in ('sha256','bytes')}
    assert pin(AUDIT/'audit-result-v1.json') == {k:life['result'][k] for k in ('sha256','bytes')}
    baseline = subprocess.check_output(['git','show',BASE+':'+MAIN],cwd=PUB)
    assert (HERE/'baseline-index.html').read_bytes() == baseline
    historical = {(MAIN,hashlib.sha256(baseline).hexdigest()):HERE/'baseline-index.html'}
    for commit,label in [('94aa6e1fd87b09dae6651385bb661cfc802dd42e','107'),('a4adb7b113338e6b8753b880356954b6a26d2086','106'),('f41da478a4a16b4c91eabe20aa8255ebdfc30830','105')]:
        raw = subprocess.check_output(['git','show',commit+':'+MAIN],cwd=PUB)
        target=HERE/('historical-index-'+label+'.html');target.write_bytes(raw)
        historical[(MAIN,hashlib.sha256(raw).hexdigest())]=target
    historical[('.gcts-active/receptor-matching-geometry-independent-20261011/positive_certificate_oracle_v1.py','7ed3f345f8938bdf465d72033f52972314db5e303f93066fdb20840d4f3f67c7')]=ROOT/'.gcts-active/receptor-matching-geometry-independent-20261011/positive_certificate_oracle_draft_7ed3f345.py'
    excluded={'task-files.json','publication.json','publication-staging.json','local-validation.json','live-hash-checks.json','browser-validation.json','turn-result.json','final-review.json','stage_publication.py','verify_live_files.py','staged-whitespace-check.json'}
    files,origins,bindings=project([
        (str(AUDIT.relative_to(ROOT)),'audit',set()),
        ('.gcts-active/family-pool-source-review-20261012','source-review',set()),
        (str(HERE.relative_to(ROOT)),'coordinator',excluded)],historical)
    def link(origin,label):
        row=next((e for e in origins if e['origin']==origin),None)
        if row: target=row['path']
        else:
            row=next(e for e in bindings if e['path']==origin);assert row['archive_member'] is None;target=row['published_path']
        return '<a href="'+html.escape(os.path.relpath(target,PREFIX))+'">'+html.escape(label)+'</a>'
    c=result['complete_census'];small={k:v for k,v in c.items() if k not in ('type_visits','rejected_binding_records')}
    previous=load(ROOT/'.gcts-active/family-proposal-progress-20261012/turn-result.json')
    phase_total=Decimal(str(terminal['full_owner_process_seconds_including_startup_and_receipt'])).quantize(Decimal('0.000000001'))
    cumulative=Decimal(str(previous['owned_sum_seconds']))+phase_total
    groups=result['groups_checked']
    with gzip.open(ROOT/'.gcts-active/family-proposal-source-20261012/preparation-evidence-v2.json.gz','rt') as f: prepared=json.load(f)
    assert [g['descriptor_id'] for g in prepared['groups']]==[g['descriptor_id'] for g in groups]
    largest=prepared['groups'][4]
    assert largest['distinct_member_count']==21 and largest['shared_member_count']==5
    cells=[]
    for row in range(24):
        owners=[i for i,component in enumerate(largest['components']) if row in component['ordered_member_rows']]
        css='seed' if not owners else ('shared' if len(owners)==2 else 'first' if owners==[0] else 'second')
        cells.append('<div class="cell '+css+'" title="'+html.escape('row '+str(row)+'; '+('original hypothesis' if not owners else 'both components' if len(owners)==2 else 'component '+str(owners[0]+1)))+'">'+math(row)+'</div>')
    controls=result['mutations'];assert len(controls)==17 and all(x['rejected'] for x in controls)
    group_table=table(['Pool','Components','Occurrences','Distinct squares','Shared squares','Fixed priority'],[[math(g['pool_index']),math(g['component_count']),math(g['occurrence_members']),math(g['distinct_members']),math(g['shared_members']),math(g['fixed_priority'])] for g in groups])
    checks=table(['Independent reconstruction','Result'],[['Primitive rules',math(229)+' licensed recipes'],['Conditional source inventory',math(171)+' families'],['Recursive source expansion',math(1845)+' leaves; '+math(630)+' assumption aliases; '+math(216)+' calls'],['Complete type enumeration',math(171)+' singles; '+math(29241)+' ordered pairs'],['Connected root/output bindings',math(5)+' accepted; '+math(0)+' rejected'],['Altered payload controls',math(17)+' rejected; self-hashes recomputed']])
    costs=table(['Measured interval','Seconds','Meaning'],[['Full dispatched audit process',math(phase_total),'Includes owner startup, pin checks, independent worker, result serialization, child reaping and owner receipt writing'],['Owner pre-write interval',math(life['owner_seconds_before_final_receipt_write']),'Nested inside the full process clock; excludes its startup and final receipt write'],['Worker pre-result-serialization interval',math(result['worker_seconds_before_result_serialization']),'Nested; phase clocks are not additional costs'],['Preparation, fixtures and this audit',math(cumulative),'Disjoint actual owned clocks across the two phases; additional reviews, reporting and publication remain separate']])
    config={'tex':{'inlineMath':[[r'\(',r'\)']],'displayMath':[[r'\[',r'\]']]},'options':{'skipHtmlTags':['script','style','pre','code']}}
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Independently validated cluster inventory · GCTS research</title><link rel="stylesheet" href="../report.css"><script>window.MathJax='''+json.dumps(config)+''';</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script><style>main{max-width:1160px}.pass{padding:18px;background:#edf6ec;border-left:5px solid #447845}.occupancy{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:7px;margin:24px 0}.cell{aspect-ratio:1;display:flex;align-items:center;justify-content:center;border:2px solid #536551;border-radius:4px}.seed{background:#e3e7e2}.first{background:#d9eefb}.second{background:#f1dff6}.shared{background:linear-gradient(135deg,#d9eefb 48%,#f1dff6 52%);border-color:#3e6552}.legend{display:flex;flex-wrap:wrap;gap:18px}.legend span{padding:8px;border-radius:4px}details{margin:16px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto;font-size:12px}.parallel{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.parallel article{background:#f4f7ef;padding:17px;border:1px solid #d2dbcc}.parallel h3{font-size:18px}@media(max-width:650px){.occupancy{grid-template-columns:repeat(6,minmax(0,1fr))}.parallel{grid-template-columns:1fr}}</style></head><body><header class="masthead"><a href="../#family-pool-audit">Research report</a><span>NOTEBOOK 109</span><a href="#sharing">Cluster sharing</a></header><main><section class="intro"><p class="eyebrow">ACTUAL INDEPENDENT RECONSTRUCTION</p><h1>The five proposals pass the independent gate.</h1><p class="deck">Their complete rule licenses, ordered receptors, declared outputs, placement identities, shared occupancy and distant markings were reconstructed independently of the producer.</p><p><a href="#checks">What passed</a> · <a href="#sharing">See the shared prefix</a> · <a href="../family-proposals/reader.html?v=26ab0339fd7d7ae15f0f18af3ac8ae29759605e9#reader">Read each colored tile as a formula</a> · <a href="#cost">Costs</a></p></section><section class="panel" id="checks"><h2>A validated inventory for the next search.</h2><p class="pass">One completed independent audit accepted the entire declared proposal pool. All altered-payload controls were rejected. This is static cluster validation; this phase performs no target proof search, native query or RL training.</p>'''+checks+group_table+'''<p>The auditor uses separately authored symbolic, body-expansion and point-state libraries. It imports no producer, production graph, lifecycle Controller, search engine or native checker. It checks every supplied descriptor field against a freshly reconstructed descriptor, including the explicit declared output when that output is not the last member.</p><p>The grammar remains restricted to one or two existing source families and one canonical embedding for each exact receptor binding. The first component binds original hypotheses; the second may bind the included first component's declared output, with at least one such link. That output is a conditional obligation in the union, never an additional seeded hypothesis. The '''+math(c['disconnected_second_bindings_outside_grammar'])+''' disconnected second-component bindings remain outside this declared grammar.</p></section><section class="panel" id="sharing"><h2>Two clusters can reuse the same prefix.</h2><p>Pool '''+math(4)+' has '+math(26)+' component-member occurrences but '+math(21)+''' distinct primitive squares. The two components have exactly the same full placement identities at rows '''+math('3,4,5,6,7')+'''. Those squares count once in the occupancy union while both source occurrences and all ordered read ports remain visible.</p><div class="legend"><span class="seed">Original hypotheses</span><span class="first">First component only</span><span class="shared">Shared by both</span><span class="second">Second component only</span></div><div class="occupancy" aria-label="Largest proposed union, rows zero through twenty-three">'''+''.join(cells)+'''</div><p>These background colors indicate component membership. The linked tile reader separately shows the blue formula markings and purple source-offset markings. With '''+math(3)+' original hypothesis squares, the union fits all '+math(24)+''' rows. Static fit does not establish that the scheduler executes this union or discovers a completed proof.</p></section><section class="panel" id="limits"><h2>What this gate establishes.</h2><p>All '''+math(171)+''' conditional source bodies are independently checked and recursively expanded. Their local assumptions become receptor aliases with no new occupancy. Every primitive witness belongs to the frozen recipient relation. Formula codes, context, theory, authority, source maps, ordered references, vertical translation and exact point values determine full placement identities.</p><p>Whole-union validation checks unit occupancy and every assigned marking, including distant points. Missing markings and assigned zero remain distinct. Only equal full primitive keys may share occupancy. Fixed priorities are independently reconstructed and bound into the whole pool authority epoch.</p><p>This gate does not enumerate the complete live candidate graph, audit scheduler decisions or establish search exhaustion. It does not demonstrate new lemma discovery, a universal native Wang compilation theorem, an unrestricted first-order calculus, learned failure markings or an RL advantage. The original source-body proofs are existing infrastructure; generating compatible bindings is the new work.</p><p>The '''+math(17)+''' corruption controls modify individual group payloads, recompute their self-hashes and compare them to independently rebuilt groups. They are not complete altered-file or owner replays. Earlier synthetic fixtures remain separately scoped and charged. Exact pinned standard JSON inputs are the parser scope.</p></section><section class="panel" id="parallel"><h2>Three parallel tracks now feed the next experiment.</h2><div class="parallel"><article><h3>Independent checking</h3><p>This actual pool gate passes. The next execution gate must audit scheduler traces, rollback and any completed certificate.</p></article><article><h3>Cluster-assisted search</h3><p>A sibling adapter is being prepared to use the five immutable whole-union proposals while retaining all primitive alternatives and allowing global forced moves to interrupt them.</p></article><article><h3>RL update checks</h3><p>A small numeric gate is being prepared for the mixture policy, score gradient and baseline update. Numeric fixtures, training and the executable policy overlay remain unrun in this phase.</p></article></div><p>ROOT owns actual activation, measured lifetimes, integration and publication. The agents prepare independent sources and reviews concurrently. A static pool PASS authorizes consideration as a search inventory; it does not bypass the global point graph or allow unknown failures to prune alternatives.</p></section><section class="panel" id="cost"><h2>Audit costs include the dispatched process.</h2>'''+costs+'''<p>The conservative combined peak is '''+math(life['kernel_conservative_peak_bytes'])+''' bytes. The prospective gates were '''+math(180)+' whole-owner seconds, '+math(175)+' supervisor seconds, '+math(170)+' child seconds and '+math(536870912)+''' peak bytes. They were fixed before execution and did not change. Owned RSS samples, child alarms, deadline checks and final kernel peaks provide resource acceptance; they do not constitute a hard operating-system memory cap.</p><p>Independent source-review metadata validation took '''+math('0.883618291')+''' seconds and is additional to the scientific owned total. Source reading and authoring are unmeasured, not zero. ROOT terminal-record writing is also outside the full child-process clock. Earlier matching phases add '''+math('50.956800624')+' and '+math('50.405773542')+''' owned seconds; still earlier inventory and failed gates remain additional.</p></section><section class="panel" id="evidence"><h2>Inspect every result and prerequisite.</h2><p>'''+link(str((AUDIT/'audit-result-v1.json').relative_to(ROOT)),'Complete independent result')+' · '+link(str((AUDIT/'audit-lifetime-v1.json').relative_to(ROOT)),'Audit lifetime and resource gate')+' · '+link(str((HERE/'audit-terminal-v1.json').relative_to(ROOT)),'Full dispatch timing')+' · '+link('.gcts-active/family-pool-source-review-20261012/source-review-v1.json','Independent prospective source review')+' · '+link(str((AUDIT/'audit-plan-v1.json').relative_to(ROOT)),'Frozen audit plan')+'''</p><p><a href="result-summary.json">Compact result</a> · <a href="origins.json">Published origins</a> · <a href="source-input-bindings.json">Exact prerequisite routes</a> · <a href="external-runtime-bindings.json">Runtime identities</a> · <a href="sources-and-inputs.zip">Additional sources and historical bytes</a></p><p>Runtime binaries are excluded; their identities are recorded separately. This page is a saved-evidence reader and executes no scientific checker. Notebook 108 retains the earlier preparation checkpoint; this audit supersedes its pending actual-pool status. The broader research program remains active.</p><details><summary>All altered payload controls</summary>'''+table(['Control','Result'],[[html.escape(m['name']),'Rejected'] for m in controls])+'''</details></section></main></body></html>'''
    (DEST/'reader.html').write_text(page);files.add(PREFIX+'reader.html')
    summary=dict(status=result['status'],goal_status='active',complete_census=small,groups=groups,mutations_rejected=len(controls),full_owner_process_seconds=str(phase_total),additional_disjoint_owned_seconds=str(phase_total),preparation_fixtures_audit_disjoint_seconds=str(cumulative),conservative_peak_bytes=life['kernel_conservative_peak_bytes'],new_proof_searches=0,new_native_queries=0,new_training_runs=0,complete_live_candidate_graph_checked=False,report_scientific_execution=False)
    (DEST/'result-summary.json').write_text(json.dumps(summary,indent=2)+'\n');files.add(PREFIX+'result-summary.json')
    previous_html=baseline.decode();assert 'RESEARCH NOTEBOOK · 108' in previous_html
    panel='<section class="panel" id="family-pool-audit"><h2>Checkpoint 109 · The complete cluster pool passes independent reconstruction</h2><p>One actual audit independently validates all '+math(5)+' receptor-adapted proposals, including '+math(5)+' shared primitive placements in the largest pair. All '+math(17)+' altered-payload controls are rejected. Full dispatched audit time: '+math(phase_total)+' seconds. <a href="family-pool-audit/reader.html?v=20261012-fpa1#sharing">Inspect the checked inventory, sharing and full costs</a>.</p><p>This validates static cluster proposals. Cluster-assisted proof search and RL remain the next execution tasks; no new theorem or training result is claimed here.</p></section>\n'
    anchor='<section class="panel" id="family-proposals">';assert previous_html.count(anchor)==1
    updated=previous_html.replace('RESEARCH NOTEBOOK · 108','RESEARCH NOTEBOOK · 109',1).replace(anchor,panel+anchor,1)
    current=ROOT/MAIN
    assert current.read_bytes()==baseline,'unrelated report edit'
    current.write_text(updated);files.add(MAIN)
    assert updated.replace(panel,'',1).replace('RESEARCH NOTEBOOK · 109','RESEARCH NOTEBOOK · 108',1)==previous_html
    manifest=[dict(path=f,**pin(ROOT/f)) for f in sorted(files)]
    (HERE/'task-files.json').write_text(json.dumps(manifest,indent=2)+'\n')
    (HERE/'local-validation.json').write_text(json.dumps(dict(status='passed_saved_evidence_projection_and_additive_main_scope',files=len(manifest),origins=len(origins),bindings=len(bindings),shared_rows=[r for r in range(24) if sum(r in z['ordered_member_rows'] for z in largest['components'])==2],all_five_descriptor_ids_match_actual_audit=True,main_reverses_exact_baseline=True,scientific_execution=False),indent=2)+'\n')
    print(json.dumps(dict(files=len(manifest),origins=len(origins),bindings=len(bindings),total_bytes=sum(p['bytes'] for p in manifest))))


if __name__=='__main__': main()
